#!/usr/bin/env node
// Regenerates everything derived from apps/<app>/app.json and apps/<app>/<version>/:
//   apps/<app>/latest/   copy of the newest version
//   apps/<app>/README.md app page with buttons
//   README.md            app list between the apps:start / apps:end markers
//
// Usage: node scripts/generate.mjs          write files
//        node scripts/generate.mjs --check  exit 1 if any generated file is out of date
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import {
  APPS_DIR,
  BUTTON_IMAGE,
  PACKAGE_FILES,
  deployUrl,
  isPrerelease,
  latestOf,
  listDirs,
  readJson,
  versionsOf,
} from "./lib.mjs";

const check = process.argv.includes("--check");
const START = "<!-- apps:start -->";
const END = "<!-- apps:end -->";
const NOTICE = "<!-- Generated by scripts/generate.mjs from app.json. Do not edit by hand. -->";

const outputs = new Map(); // path -> content

function button(dir) {
  return `[![Deploy to Azure](${BUTTON_IMAGE})](${deployUrl(dir)})`;
}

function appReadme(app, meta, versions, latest) {
  const lines = [NOTICE, "", `# ${meta.title}`, "", meta.description.trim(), ""];
  if (latest) {
    lines.push(`Latest version: **${latest}**`, "", button(`${APPS_DIR}/${app}/latest`), "");
  } else {
    lines.push("No version published yet.", "");
  }
  if (meta.requirements?.length) {
    lines.push("## Requirements", "", ...meta.requirements.map((r) => `- ${r}`), "");
  }
  const links = [];
  if (meta.homepage) links.push(`- Product page: ${meta.homepage}`);
  if (meta.marketplaceUrl) links.push(`- Azure Marketplace: ${meta.marketplaceUrl}`);
  if (links.length) lines.push("## Links", "", ...links, "");
  if (versions.length) {
    lines.push("## All versions", "", "| Version | Deploy | Template |", "|---|---|---|");
    for (const v of versions) {
      const label = isPrerelease(v) ? `${v} (preview)` : v;
      lines.push(`| ${label} | ${button(`${APPS_DIR}/${app}/${v}`)} | [azuredeploy.json](${v}/azuredeploy.json) |`);
    }
    lines.push("");
  }
  return lines.join("\n");
}

const rows = [];
for (const app of listDirs(APPS_DIR)) {
  const appDir = join(APPS_DIR, app);
  const metaPath = join(appDir, "app.json");
  if (!existsSync(metaPath)) {
    console.error(`skip ${appDir}: no app.json (validate.mjs reports this)`);
    continue;
  }
  const meta = readJson(metaPath);
  const versions = versionsOf(appDir);
  const latest = latestOf(versions);
  if (latest) {
    for (const file of PACKAGE_FILES) {
      outputs.set(join(appDir, "latest", file), readFileSync(join(appDir, latest, file), "utf8"));
    }
  }
  outputs.set(join(appDir, "README.md"), appReadme(app, meta, versions, latest));
  const summary = meta.description.trim().split(/\n\s*\n/)[0].replace(/\s+/g, " ");
  rows.push(
    `| [${meta.title}](${APPS_DIR}/${app}/README.md) | ${summary} | ${latest ?? "-"} | ${
      latest ? button(`${APPS_DIR}/${app}/latest`) : "-"
    } |`,
  );
}

const table = rows.length
  ? ["| Application | Description | Version | Deploy |", "|---|---|---|---|", ...rows].join("\n")
  : "_No applications published yet._";
const rootReadme = readFileSync("README.md", "utf8");
const s = rootReadme.indexOf(START);
const e = rootReadme.indexOf(END);
if (s < 0 || e < s) {
  console.error(`README.md must contain ${START} and ${END}`);
  process.exit(1);
}
outputs.set(
  "README.md",
  `${rootReadme.slice(0, s + START.length)}\n${NOTICE}\n\n${table}\n\n${rootReadme.slice(e)}`,
);

let stale = 0;
for (const [path, content] of outputs) {
  const current = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (current === content) continue;
  if (check) {
    console.error(`out of date: ${path}`);
    stale++;
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`wrote ${path}`);
  }
}
if (stale) {
  console.error(`\n${stale} generated file(s) out of date. Run: node scripts/generate.mjs`);
  process.exit(1);
}
